window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-83a7c2b75e6da548"]={"versions": [{"id": "FIG-83a7c2b75e6da548", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> Spezifiziert im Template <em>AUTOSAR FO TPS SecurityExtractTemplate</em> (Release R23-11). Definiert die statische Datenmodellierung für das Intrusion Detection System Management (IdsM) im Rahmen des Security Extracts (<code>SECXT</code>).</li>\n<li><strong>Technischer Zweck:</strong> Parametrierung und Zuordnung von Kontext- und Filterungseigenschaften (<code>SecurityEventContextProps</code>) zu spezifischen Sicherheitsereignissen (<code>SecurityEventDefinition</code>) sowie die Strukturierung zugehöriger Kontextdaten (<code>SecurityEventContextData</code>) innerhalb von Mapping-Containern (<code>SecurityEventContextMapping</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextProps</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:</li>\n<li>Zentraler Eigenschafts-Container zur Konfiguration eines Sicherheitsereignisses.</li>\n<li>Attribute:</li>\n<li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>: Initialer Betriebsmodus für das Reporting (z. B. <em>OFF</em>, <em>BRIEF</em>, <em>DETAILED</em>).</li>\n<li><code>persistentStorage: Boolean [0..1]</code>: Steuert, ob das Event im Flash/NvM über Reset-Zyklen hinweg persistent vorgehalten werden muss.</li>\n<li><code>sensorInstanceId: PositiveInteger [0..1]</code>: Eindeutige Instanz-ID des meldenden Security-Sensors bei Mehrfachinstanziierung.</li>\n<li><code>severity: PositiveInteger [0..1]</code>: Prioritäts- bzw. Dringlichkeitsstufe des Events zur Schwellwertfilterung im IdsM.</li>\n<li><strong><code>SecurityEventDefinition</code></strong> <em>(Spezialisierung von <code>IdsCommonElement</code>)</em>:</li>\n<li>Repräsentiert die generische Definition des Sicherheitsereignisses.</li>\n<li>Attribut: <code>id: PositiveInteger [0..1]</code> (eindeutige standardisierte oder herstellerspezifische Event-ID).</li>\n<li><strong><code>SecurityEventContextData</code></strong>:</li>\n<li>Datenstruktur-Container zur Definition der bei Event-Auslösung zu erfassenden Kontextdaten (Payload/Zusatzinformationen).</li>\n<li><strong><code>SecurityEventContextMapping</code></strong> <em>(Spezialisierung von <code>IdsMapping</code>)</em>:</li>\n<li>Mapping-Element zur Bindung der kontextuellen Eigenschaften an ein Gesamtsystem- oder ECU-Mapping.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Varianzen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextMapping</code> $\\blacklozenge$ $\\xrightarrow{\\text{+mappedSecurityEvent}}$ <code>SecurityEventContextProps</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..*</code> (ein Mapping aggregiert mehrere Kontextkonfigurationen).</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = preCompileTime</code>.</li>\n<li><strong><code>SecurityEventContextProps</code> $\\blacklozenge$ $\\xrightarrow{\\text{+contextData}}$ <code>SecurityEventContextData</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..1</code> (optionaler Payload-Kontext pro Eigenschaftssatz).</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><strong><code>SecurityEventContextProps</code> $\\xrightarrow{\\text{+securityEvent}}$ <code>SecurityEventDefinition</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation (Referenz).</li>\n<li><em>Kardinalität:</em> <code>0..1</code> (verweist auf die zugrundeliegende Event-Definition).</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>atp.Status = candidate</code>, <code>vh.latestBindingTime = systemDesignTime</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches M2-Metamodell handelt, liegt kein Laufzeit-Sequenzdiagramm vor. Die modellierten Strukturen steuern jedoch deterministisch das Laufzeitverhalten im IdsM-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Triggerung:</strong> Ein BSW-Modul oder eine SW-C (Security Sensor) detektiert eine Anomalie und ruft die IdsM-Meldeschnittstelle auf (z. B. <code>IdsM_SetSecurityEvent(EventId, ...)</code>).</li>\n<li><strong>Identifikation & Instanzauflösung:</strong> Das IdsM schlägt die referenzierte <code>SecurityEventDefinition.id</code> nach und verknüpft sie mit der übergebenen oder modellierten <code>sensorInstanceId</code>.</li>\n<li><strong>Filter- & Weiterleitungslogik:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung des <code>defaultReportingMode</code> (unter Berücksichtigung etwaiger via UDS/Diagnose übersteuerter Zustände).</li>\n<li>Schwellwertabgleich über <code>severity</code>. Liegt die Schwere unterhalb des IdsM-Filters, wird das Event verworfen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Persistenz & Kontextspeicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>persistentStorage == TRUE</code> initiiert das IdsM die asynchrone Sicherung des Event-Puffers via NvM.</li>\n<li>Serialisierung der erfassten Messwerte gemäß Schema aus <code>SecurityEventContextData</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Bindungszeiten & Toolchain (<code>vh.latestBindingTime</code>):</strong></li>\n<li>Die Verknüpfung von <code>SecurityEventContextProps</code> zu <code>SecurityEventDefinition</code> muss spätestens zur <code>systemDesignTime</code> aufgelöst sein (Systemextraktion/OEM-Lieferung).</li>\n<li>Das Mapping (<code>mappedSecurityEvent</code>) erlaubt Bindung bis <code>preCompileTime</code>. Der BSW-Konfigurator generiert daraus statische C-Konfigurationsstrukturen (z. B. <code>IdsM_PBcfg.c</code> / <code>IdsM_Cfg.h</code>).</li>\n<li><strong>ARXML-Splitting (<code>atpSplitable</code>):</strong></li>\n<li>Alle Aggregationen sind als <code>«atpSplitable»</code> definiert. Sicherheitsdefinitionen können herstellerseitig (OEM) vorgegeben und lieferantenseitig (Tier-1) in separaten ARXML-Fragmenten mit konkreten Sensor-Instanzen und Kontextstrukturen gemergt werden.</li>\n<li><strong>Konfigurationsverträge (TPS_SECXT_01016, TPS_SECXT_01040):</strong></li>\n<li>Fehlt <code>defaultReportingMode</code>, greift der globale IdsM-Default.</li>\n<li>Wenn <code>SecurityEventContextData</code> instanziiert ist, muss der aufrufende Sensor-Treiber sicherstellen, dass Puffergröße und Datentypen exakt mit dem im BSW-Generator allokierten Puffer korrespondieren, um Pufferüberläufe im IdsM-Event-Buffer zu verhindern.</li>\n</ul>"}, {"id": "FIG-fdcadd0b45f7e69e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> Spezifiziert im Template <em>AUTOSAR FO TPS SecurityExtractTemplate</em> (Release R24-11). Definiert die statische Datenmodellierung für das Intrusion Detection System Management (IdsM) im Rahmen des Security Extracts (<code>SECXT</code>).</li>\n<li><strong>Technischer Zweck:</strong> Parametrierung und Zuordnung von Kontext- und Filterungseigenschaften (<code>SecurityEventContextProps</code>) zu Sicherheitsereignissen (<code>SecurityEventDefinition</code>) sowie die detaillierte semantische und typisierte Spezifikation der Kontextdaten (<code>SecurityEventContextDataDefinition</code>, <code>SecurityEventContextDataElement</code>) inklusive Repräsentation auf Netzwerk- und Datentypebene über AUTOSAR-Basiselemente (<code>SwDataDefProps</code>, <code>SwBaseType</code>, <code>CompuMethod</code>, <code>Unit</code>) innerhalb von Mapping-Containern (<code>SecurityEventContextMapping</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextProps</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:</li>\n<li>Zentraler Eigenschafts-Container zur Konfiguration eines Sicherheitsereignisses.</li>\n<li>Attribute:</li>\n<li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>: Initialer Betriebsmodus für das Reporting.</li>\n<li><code>persistentStorage: Boolean [0..1]</code>: Steuert die persistente Vorhaltung des Events im Flash/NvM.</li>\n<li><code>sensorInstanceId: PositiveInteger [0..1]</code>: Eindeutige Instanz-ID des meldenden Security-Sensors.</li>\n<li><code>severity: PositiveInteger [0..1]</code>: Prioritäts- bzw. Dringlichkeitsstufe des Events zur Schwellwertfilterung im IdsM.</li>\n<li><strong><code>SecurityEventDefinition</code></strong> <em>(Spezialisierung von <code>IdsCommonElement</code>)</em>:</li>\n<li>Repräsentiert die generische Definition des Sicherheitsereignisses.</li>\n<li>Attribut: <code>id: PositiveInteger [0..1]</code> (eindeutige Event-ID).</li>\n<li><strong><code>SecurityEventContextMapping</code></strong> <em>(Spezialisierung von <code>IdsMapping</code>)</em>:</li>\n<li>Mapping-Element zur Bindung der kontextuellen Eigenschaften an ein Gesamtsystem- oder ECU-Mapping.</li>\n<li><strong><code>SecurityEventContextDataDefinition</code></strong> <em>(Spezialisierung von <code>IdsCommonElement</code>)</em>:</li>\n<li>Repräsentiert die versionsabhängige Definition der Kontextdatenstruktur eines Sicherheitsereignisses.</li>\n<li>Attribut: <code>version: PositiveInteger [0..1]</code>: Versionsnummer der Kontextdaten-Definition.</li>\n<li><strong><code>SecurityEventContextDataElement</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:</li>\n<li>Ein einzelnes Element oder Feld innerhalb der Kontextdatenstruktur.</li>\n<li>Attribut: <code>maxLength: PositiveInteger [0..1]</code>: Maximale Länge des Datenelements.</li>\n<li><strong><code>SwDataDefProps</code></strong> <em>(Stereotyp <code>«atpVariation»</code>)</em>:</li>\n<li>Datendefinitionseigenschaften zur Beschreibung von Darstellungs- und Typaspekten.</li>\n<li><strong><code>SwBaseType</code></strong> <em>(Spezialisierung von <code>BaseType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>)</em>:</li>\n<li>Definiert den elementaren softwaretechnischen Datentyp.</li>\n<li><strong><code>CompuMethod</code></strong> <em>(Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>)</em>:</li>\n<li>Definiert Berechnungs- und Skalierungsregeln zur Umrechnung zwischen internen und physikalischen Werten.</li>\n<li><strong><code>Unit</code></strong> <em>(Spezialisierung von <code>ARElement</code>)</em>:</li>\n<li>Definiert physikalische Einheiten.</li>\n<li>Attribute:</li>\n<li><code>factorSiToUnit: Float [0..1]</code></li>\n<li><code>offsetSiToUnit: Float [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Varianzen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextMapping</code> $\\blacklozenge$ $\\xrightarrow{\\text{+mappedSecurityEvent}}$ <code>SecurityEventContextProps</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..*</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>vh.latestBindingTime = preCompileTime</code>, <code>atp.Status = candidate</code>.</li>\n<li><strong><code>SecurityEventContextProps</code> $\\xrightarrow{\\text{+securityEvent}}$ <code>SecurityEventDefinition</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation (Referenz).</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>vh.latestBindingTime = systemDesignTime</code>, <code>atp.Status = candidate</code>.</li>\n<li><strong><code>SecurityEventDefinition</code> $\\blacklozenge$ $\\xrightarrow{\\text{+securityEventContextDataDefinition}}$ <code>SecurityEventContextDataDefinition</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..*</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><strong><code>SecurityEventContextDataDefinition</code> $\\blacklozenge$ $\\xrightarrow{\\text{+contextDataElement}}$ <code>SecurityEventContextDataElement</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..* {ordered}</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><strong><code>SecurityEventContextDataElement</code> $\\blacklozenge$ $\\xrightarrow{\\text{+nestedContextData}}$ <code>SecurityEventContextDataElement</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Rekursive Komposition (Schachtelung hierarchischer Datenstrukturen).</li>\n<li><em>Kardinalität:</em> <code>0..* {ordered}</code>.</li>\n<li><strong><code>SecurityEventContextDataElement</code> $\\blacklozenge$ $\\xrightarrow{\\text{+networkRepresentation}}$ <code>SwDataDefProps</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpSplitable»</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+compuMethod}}$ <code>CompuMethod</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+baseType}}$ <code>SwBaseType</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+unit}}$ <code>Unit</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>CompuMethod</code> $\\xrightarrow{\\text{+unit}}$ <code>Unit</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches M2-Metamodell handelt, liegt kein Laufzeit-Sequenzdiagramm vor. Die modellierten Strukturen steuern jedoch deterministisch das Laufzeitverhalten im IdsM-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Triggerung:</strong> Ein BSW-Modul oder eine SW-C (Security Sensor) meldet ein Sicherheitsereignis unter Angabe von Event-ID, Instanz-ID und Kontextdaten-Payload.</li>\n<li><strong>Filterung & Auswertung:</strong> Das IdsM liest die parametrierten <code>SecurityEventContextProps</code> (<code>defaultReportingMode</code>, <code>severity</code>, <code>persistentStorage</code>), prüft Schwellwerte und Betriebsmodi und qualifiziert das Ereignis.</li>\n<li><strong>Kontextdaten-Serialisierung & Interpretation:</strong> Anhand der zugeordneten <code>SecurityEventContextDataDefinition</code> und der geordneten <code>SecurityEventContextDataElement</code>-Strukturen wird der Kontextdatenstrom typkonform gemäß <code>networkRepresentation</code> (<code>SwBaseType</code>, <code>CompuMethod</code>, <code>Unit</code>) interpretiert, serialisiert und für Reporting oder NvM-Ablage verarbeitet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle im SECXT-Workflow:</strong> Definiert die typisierte Struktur von Security-Event-Payloads im AUTOSAR Security Extract. Die Kontextdaten werden direkt an der Event-Definition verankert und über geordnete Datenelemente semantisch exakt typisiert.</li>\n<li><strong>Variabilitätsmanagement:</strong></li>\n<li><code>+securityEvent</code> bindet zur <code>systemDesignTime</code>.</li>\n<li><code>+mappedSecurityEvent</code> bindet zur <code>preCompileTime</code>.</li>\n<li>Definitionen und Datenelemente unterstützen Splitbarkeit und Variation (<code>«atpVariation, atpSplitable»</code>).</li>\n<li><strong>Integrationshinweise:</strong></li>\n<li>Durch die geordnete Abfolge (<code>{ordered}</code>) der <code>SecurityEventContextDataElement</code>-Einträge und die Unterstützung von Schachtelungen (<code>nestedContextData</code>) können komplexe Protokollstrukturen und binäre Payloads deterministisch abgebildet werden.</li>\n<li><code>SwDataDefProps</code> ermöglicht die nahtlose Einbindung bestehender AUTOSAR-Standardelemente zur Datenumrechnung und Datentypisierung.</li>\n</ul>"}, {"id": "FIG-df1da72bcf0f3a71", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> Spezifiziert im Template <em>AUTOSAR FO TPS SecurityExtractTemplate</em> (Release R24-11). Definiert die statische Datenmodellierung für das Intrusion Detection System Management (IdsM) im Rahmen des Security Extracts (<code>SECXT</code>).</li>\n<li><strong>Technischer Zweck:</strong> Parametrierung und Zuordnung von Kontext- und Filterungseigenschaften (<code>SecurityEventContextProps</code>) zu Sicherheitsereignissen (<code>SecurityEventDefinition</code>) sowie die detaillierte semantische und typisierte Spezifikation der Kontextdaten (<code>SecurityEventContextDataDefinition</code>, <code>SecurityEventContextDataElement</code>) inklusive Repräsentation auf Netzwerk- und Datentypebene über AUTOSAR-Basiselemente (<code>SwDataDefProps</code>, <code>SwBaseType</code>, <code>CompuMethod</code>, <code>Unit</code>) innerhalb von Mapping-Containern (<code>SecurityEventContextMapping</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextProps</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:</li>\n<li>Zentraler Eigenschafts-Container zur Konfiguration eines Sicherheitsereignisses.</li>\n<li>Attribute:</li>\n<li><code>defaultReportingMode: SecurityEventReportingModeEnum [0..1]</code>: Initialer Betriebsmodus für das Reporting.</li>\n<li><code>persistentStorage: Boolean [0..1]</code>: Steuert die persistente Vorhaltung des Events im Flash/NvM.</li>\n<li><code>sensorInstanceId: PositiveInteger [0..1]</code>: Eindeutige Instanz-ID des meldenden Security-Sensors.</li>\n<li><code>severity: PositiveInteger [0..1]</code>: Prioritäts- bzw. Dringlichkeitsstufe des Events zur Schwellwertfilterung im IdsM.</li>\n<li><strong><code>SecurityEventDefinition</code></strong> <em>(Spezialisierung von <code>IdsCommonElement</code>)</em>:</li>\n<li>Repräsentiert die generische Definition des Sicherheitsereignisses.</li>\n<li>Attribut: <code>id: PositiveInteger [0..1]</code> (eindeutige Event-ID).</li>\n<li><strong><code>SecurityEventContextMapping</code></strong> <em>(Spezialisierung von <code>IdsMapping</code>)</em>:</li>\n<li>Mapping-Element zur Bindung der kontextuellen Eigenschaften an ein Gesamtsystem- oder ECU-Mapping.</li>\n<li><strong><code>SecurityEventContextDataDefinition</code></strong> <em>(Spezialisierung von <code>IdsCommonElement</code>)</em>:</li>\n<li>Repräsentiert die versionsabhängige Definition der Kontextdatenstruktur eines Sicherheitsereignisses.</li>\n<li>Attribut: <code>version: PositiveInteger [0..1]</code>: Versionsnummer der Kontextdaten-Definition.</li>\n<li><strong><code>SecurityEventContextDataElement</code></strong> <em>(Spezialisierung von <code>Identifiable</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>)</em>:</li>\n<li>Ein einzelnes Element oder Feld innerhalb der Kontextdatenstruktur, als Blueprint entwerfbar.</li>\n<li>Attribut: <code>maxLength: PositiveInteger [0..1]</code>: Maximale Länge des Datenelements.</li>\n<li><strong><code>SwDataDefProps</code></strong> <em>(Stereotyp <code>«atpVariation»</code>)</em>:</li>\n<li>Datendefinitionseigenschaften zur Beschreibung von Darstellungs- und Typaspekten.</li>\n<li><strong><code>SwBaseType</code></strong> <em>(Spezialisierung von <code>BaseType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>)</em>:</li>\n<li>Definiert den elementaren softwaretechnischen Datentyp.</li>\n<li><strong><code>CompuMethod</code></strong> <em>(Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>)</em>:</li>\n<li>Definiert Berechnungs- und Skalierungsregeln zur Umrechnung zwischen internen und physikalischen Werten.</li>\n<li><strong><code>Unit</code></strong> <em>(Spezialisierung von <code>ARElement</code>)</em>:</li>\n<li>Definiert physikalische Einheiten.</li>\n<li>Attribute:</li>\n<li><code>factorSiToUnit: Float [0..1]</code></li>\n<li><code>offsetSiToUnit: Float [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Varianzen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SecurityEventContextMapping</code> $\\blacklozenge$ $\\xrightarrow{\\text{+mappedSecurityEvent}}$ <code>SecurityEventContextProps</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..*</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>vh.latestBindingTime = preCompileTime</code>, <code>atp.Status = candidate</code>.</li>\n<li><strong><code>SecurityEventContextProps</code> $\\xrightarrow{\\text{+securityEvent}}$ <code>SecurityEventDefinition</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation (Referenz).</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><em>Variations-Tags:</em> <code>vh.latestBindingTime = systemDesignTime</code>, <code>atp.Status = candidate</code>.</li>\n<li><strong><code>SecurityEventDefinition</code> $\\blacklozenge$ $\\xrightarrow{\\text{+securityEventContextDataDefinition}}$ <code>SecurityEventContextDataDefinition</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..*</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><strong><code>SecurityEventContextDataDefinition</code> $\\blacklozenge$ $\\xrightarrow{\\text{+contextDataElement}}$ <code>SecurityEventContextDataElement</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..* {ordered}</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpVariation, atpSplitable»</code>.</li>\n<li><strong><code>SecurityEventContextDataElement</code> $\\blacklozenge$ $\\xrightarrow{\\text{+nestedContextData}}$ <code>SecurityEventContextDataElement</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Rekursive Komposition (Schachtelung hierarchischer Datenstrukturen).</li>\n<li><em>Kardinalität:</em> <code>0..* {ordered}</code>.</li>\n<li><strong><code>SecurityEventContextDataElement</code> $\\blacklozenge$ $\\xrightarrow{\\text{+networkRepresentation}}$ <code>SwDataDefProps</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Komposition.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><em>Stereotypen:</em> <code>«atpSplitable»</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+compuMethod}}$ <code>CompuMethod</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+baseType}}$ <code>SwBaseType</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>SwDataDefProps</code> $\\xrightarrow{\\text{+unit}}$ <code>Unit</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n<li><strong><code>CompuMethod</code> $\\xrightarrow{\\text{+unit}}$ <code>Unit</code>:</strong></li>\n<li><em>Beziehungstyp:</em> Gerichtete Assoziation.</li>\n<li><em>Kardinalität:</em> <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches M2-Metamodell handelt, liegt kein Laufzeit-Sequenzdiagramm vor. Die modellierten Strukturen steuern jedoch deterministisch das Laufzeitverhalten im IdsM-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Triggerung:</strong> Ein BSW-Modul oder eine SW-C (Security Sensor) meldet ein Sicherheitsereignis unter Angabe von Event-ID, Instanz-ID und Kontextdaten-Payload.</li>\n<li><strong>Filterung & Auswertung:</strong> Das IdsM liest die parametrierten <code>SecurityEventContextProps</code> (<code>defaultReportingMode</code>, <code>severity</code>, <code>persistentStorage</code>), prüft Schwellwerte und Betriebsmodi und qualifiziert das Ereignis.</li>\n<li><strong>Kontextdaten-Serialisierung & Interpretation:</strong> Anhand der zugeordneten <code>SecurityEventContextDataDefinition</code> und der geordneten <code>SecurityEventContextDataElement</code>-Strukturen wird der Kontextdatenstrom typkonform gemäß <code>networkRepresentation</code> (<code>SwBaseType</code>, <code>CompuMethod</code>, <code>Unit</code>) interpretiert, serialisiert und für Reporting oder NvM-Ablage verarbeitet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle im SECXT-Workflow:</strong> Definiert die typisierte Struktur von Security-Event-Payloads im AUTOSAR Security Extract. Die Kontextdaten werden direkt an der Event-Definition verankert und über geordnete Datenelemente semantisch exakt typisiert.</li>\n<li><strong>Variabilitätsmanagement:</strong></li>\n<li><code>+securityEvent</code> bindet zur <code>systemDesignTime</code>.</li>\n<li><code>+mappedSecurityEvent</code> bindet zur <code>preCompileTime</code>.</li>\n<li>Definitionen und Datenelemente unterstützen Splitbarkeit und Variation (<code>«atpVariation, atpSplitable»</code>).</li>\n<li><strong>Integrationshinweise:</strong></li>\n<li>Durch die geordnete Abfolge (<code>{ordered}</code>) der <code>SecurityEventContextDataElement</code>-Einträge und die Unterstützung von Schachtelungen (<code>nestedContextData</code>) können komplexe Protokollstrukturen und binäre Payloads deterministisch abgebildet werden.</li>\n<li><code>SwDataDefProps</code> ermöglicht die nahtlose Einbindung bestehender AUTOSAR-Standardelemente zur Datenumrechnung und Datentypisierung.</li>\n</ul>"}], "trans": [{"from": "FIG-83a7c2b75e6da548", "to": "FIG-fdcadd0b45f7e69e", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Das Element <code>SecurityEventContextData</code> und dessen Aggregation <code>+contextData [0..1]</code> an <code>SecurityEventContextProps</code> entfallen.</li>\n<li><code>SecurityEventDefinition</code> aggregiert neu <code>SecurityEventContextDataDefinition</code> über die Komposition <code>+securityEventContextDataDefinition</code> mit Kardinalität <code>0..*</code> und Stereotypen <code>«atpVariation, atpSplitable»</code>.</li>\n<li>Neu eingeführtes Element <code>SecurityEventContextDataDefinition</code> (spezialisiert <code>IdsCommonElement</code>) mit Attribut <code>version: PositiveInteger [0..1]</code>.</li>\n<li><code>SecurityEventContextDataDefinition</code> aggregiert <code>SecurityEventContextDataElement</code> über die Komposition <code>+contextDataElement</code> mit Kardinalität <code>0..* {ordered}</code> und Stereotypen <code>«atpVariation, atpSplitable»</code>.</li>\n<li>Neu eingeführtes Element <code>SecurityEventContextDataElement</code> (spezialisiert <code>Identifiable</code>) mit Attribut <code>maxLength: PositiveInteger [0..1]</code>.</li>\n<li><code>SecurityEventContextDataElement</code> besitzt eine rekursive Komposition auf sich selbst mit Rollenbezeichnung <code>+nestedContextData</code> und Kardinalität <code>0..* {ordered}</code>.</li>\n<li><code>SecurityEventContextDataElement</code> aggregiert <code>SwDataDefProps</code> (Stereotyp <code>«atpVariation»</code>) über die Komposition <code>+networkRepresentation</code> mit Kardinalität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code>.</li>\n<li><code>SwDataDefProps</code> referenziert über Assoziationen:</li>\n<li><code>CompuMethod</code> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>) über <code>+compuMethod [0..1]</code>,</li>\n<li><code>SwBaseType</code> (Spezialisierung von <code>BaseType</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>) über <code>+baseType [0..1]</code>,</li>\n<li><code>Unit</code> (Spezialisierung von <code>ARElement</code>) über <code>+unit [0..1]</code>.</li>\n<li><code>CompuMethod</code> referenziert über die Assoziation <code>+unit [0..1]</code> das Element <code>Unit</code> mit Attributen <code>factorSiToUnit: Float [0..1]</code> und <code>offsetSiToUnit: Float [0..1]</code>.</li>\n</ul>"}, {"from": "FIG-fdcadd0b45f7e69e", "to": "FIG-df1da72bcf0f3a71", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>SecurityEventContextDataElement</code>: Zusätzliche Stereotypen- bzw. Blueprint-Klassifikation <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> im Klassenkopf ergänzt.</li>\n</ul>"}]};
